window.kbPageData["views/entry/k-3d4202fbfb0efd8b"] = {"key":"entry/k-3d4202fbfb0efd8b","state":{"route":"entry/k-3d4202fbfb0efd8b"},"node":{"id":"k-3d4202fbfb0efd8b","mode":"k","title":"国务院《教育发展“十五五”规划》（6 月）","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["modern"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["公共管理"],"时间索引":["年度事件或数据"],"来源主题":["重要文件"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"国务院《教育发展“十五五”规划》（6 月）","slug":"0c16d02ff753"}],"directorySummary":"考点十六 国务院《教育发展“十五五”规划》（6 月）\n规划坚持党对教育事业的全面领导，坚持教育优先发展，牢牢把握教育的政治属性、人民属\n性、战略属性，聚焦高质量教育体系建设，一体推进教育科技人才发展，培养德智体美劳全面\n发展的社会主义建设者和接班人，推动教育强国建设迈上新台阶。目标到 2030 年，…","sources":[{"id":"af0df0c8252e375f","label":"国务院《教育发展“十五五”规划》（6 月）","topic":"重要文件","category":"时政","text":"考点十六 国务院《教育发展“十五五”规划》（6 月）\n规划坚持党对教育事业的全面领导，坚持教育优先发展，牢牢把握教育的政治属性、人民属\n性、战略属性，聚焦高质量教育体系建设，一体推进教育科技人才发展，培养德智体美劳全面\n发展的社会主义建设者和接班人，推动教育强国建设迈上新台阶。目标到 2030 年，教育强国\n建设取得显著成效，高质量教育体系基本建成。具体举措包括：大力推进健康学校建设，坚持\n健康第一的教育理念，落实中小学生每天综合体育活动时间不低于 2 小时，推行“课间 15 分\n钟”，广泛开展“三大球”比赛，使每个学生至少掌握 1 项体育技能；大力发展公办幼儿园、\n提高公办幼儿园学位占比；稳步扩大免费教育范围，探索延长义务教育年限。","source":{"doc":"4e539a366dce19555ccf","first":15,"last":15,"page":15,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-3d4202fbfb0efd8b":[]}};
